local KTool = CS.Engine.Lib.KTool
local cs_coroutine = require("XLua.cs_coroutine")
--- from: Assets/BundleResources/Prefabs/ChapterNew/ChapterNormal.prefab > name: ScrollingGroup
---@class ChapterBattleRoot
---@field Env                           	ChapterBattleRoot
---@field controller                    	Engine.Modules.LuaBehaviour
---@field ScrollingGroup                	UnityEngine.RectTransform               	@ 0
---@field BattleTxt                     	UnityEngine.RectTransform               	@ 1
local ChapterBattleRoot = Class('ChapterBattleRoot')
local LoopType = CS.DG.Tweening.LoopType
local Ease = CS.DG.Tweening.Ease
local CanvasGroup = CS.UnityEngine.CanvasGroup

local startColor = Color.New(1, 1, 1, 0)
local endColor = Color.New(1, 1, 1, 1)

local BattleType = {
    Tween = 1,      -- 从右到左的弹幕
    ColorAlpha = 2  -- 固定位置的弹幕 出现和消失要修改透明度
}

function ChapterBattleRoot:__init()
    self.isContinue = false
    self.cacheNode = {}
    self.cos = {}
    self.tween = {}
end

function ChapterBattleRoot:__delete()

end

function ChapterBattleRoot:Awake()
    local width = self.ScrollingGroup.rect.width
    self.RandomPos = Vector2.New(width/2,260)
    self:InsertDescNodeGo(self.BattleTxt.gameObject)
end

function ChapterBattleRoot:StartBattle(vo)
    self:StopBattle()
    CfUtils.SetActive(self.ScrollingGroup.gameObject,true)
    local ids = string.split(vo.battleGroupId,'_')
    if table.count(ids) > 0 then
        self.isContinue = checkNumber(ids[2]) == 1
    end

    local battleVos = self:GetBattleVos(vo.battleGroupId)
    if table.count(battleVos) > 0 then
        for i, v in pairs(battleVos) do
            self.cos[i] = cs_coroutine.start(function()
                local go = self:GetCacheGo()
                if isNull(go) then
                    go = CS.UnityEngine.GameObject.Instantiate(self.BattleTxt.gameObject)
                    KTool.SetParent(go,self.ScrollingGroup.gameObject,false)
                end
                CfUtils.FillText(go,v.bulletText)
                if v.bulletType == BattleType.Tween then
                    CfUtils.SetActive(go.gameObject,true)
                    cs_coroutine.yield_return(CS.Engine.Lib.Yielders.EndOfFrame)
                    self:StartTweenBattle(go,v,i)
                elseif v.bulletType == BattleType.ColorAlpha then
                    self:StartAlphaBattle(go,v,i)
                end
            end)
        end
    end
end

function ChapterBattleRoot:StartAlphaBattle(go,v,i)
    local pos = Vector3(checkNumber(v.startPosition[1]), checkNumber(v.startPosition[2]), 0)
    local canvasGroup = go.gameObject:GetComponent(typeof(CanvasGroup))
    if isNull(canvasGroup) then
        return
    end
    CfUtils.SetActive(go.gameObject,true)
    canvasGroup.alpha = 0
    go.transform.localPosition = pos
    self.tween[i] = canvasGroup:DOFade(1, 1):SetDelay(v.IntervalTime):SetEase(Ease.Linear):OnComplete(function()
        canvasGroup.alpha = 1
        self.tween[i] = nil
    end)
    cs_coroutine.yield_return(CS.Engine.Lib.Yielders.GetWaitForSeconds(v.runningTime - 2))
    self.tween[i] = canvasGroup:DOFade(0, 1):SetDelay(v.IntervalTime):SetEase(Ease.Linear):OnComplete(function()
        canvasGroup.alpha = 0
        self:InsertDescNodeGo(go)
        canvasGroup.alpha = 1
        self.tween[i] = nil
    end)
end

function ChapterBattleRoot:StartTweenBattle(go,v,i)
    local startPos, endPos
    if v.isRandom then
        local y = math.random(- self.RandomPos.y,self.RandomPos.y)
        startPos = Vector3(self.RandomPos.x, y, 0)
        local txtWidth = go.transform.rect.width
        endPos = Vector3(-self.RandomPos.x - txtWidth, y, 0)
    else
        startPos = Vector3(self.RandomPos.x, checkNumber(v.startPosition[2]), 0)
        local txtWidth = go.transform.rect.width
        endPos = Vector3(-self.RandomPos.x - txtWidth, checkNumber(v.endPosition[2]), 0)
    end
    go.transform.localPosition = startPos

    ---随机位置  循环的时候 要重新随机
    if v.isRandom then
        if self.isContinue then
            self.tween[i] = go.transform:DOLocalMove(endPos,v.runningTime):SetDelay(v.IntervalTime):SetEase(Ease.Linear):OnComplete(function()
                self:StartTweenBattle(go,v,i)
            end)
        else
            self.tween[i] = go.transform:DOLocalMove(endPos,v.runningTime):SetDelay(v.IntervalTime):SetEase(Ease.Linear):OnComplete(function()
                self:InsertDescNodeGo(go)
                cs_coroutine.stop(self.cos[i])
                self.cos[i] = nil
                self.tween[i] = nil
            end)
        end
    else
        if self.isContinue then
            self.tween[i] = go.transform:DOLocalMove(endPos,v.runningTime):SetDelay(v.IntervalTime):SetEase(Ease.Linear):SetLoops(-1, LoopType.Restart):OnComplete(function()

            end)
        else
            self.tween[i] = go.transform:DOLocalMove(endPos,v.runningTime):SetDelay(v.IntervalTime):SetEase(Ease.Linear):OnComplete(function()
                self:InsertDescNodeGo(go)
                cs_coroutine.stop(self.cos[i])
                self.cos[i] = nil
                self.tween[i] = nil
            end)
        end
    end
end

function ChapterBattleRoot:StopBattle()
    self:CleanTweenAndCo()
    self.cacheNode = {}
    for i = 1, self.ScrollingGroup.transform.childCount do
        local go = self.ScrollingGroup.transform:GetChild(i - 1)
        self:InsertDescNodeGo(go)
    end
end

function ChapterBattleRoot:CleanTweenAndCo()
    for i, v in pairs(self.cos) do
        if not isNull(v) then
            cs_coroutine.stop(v)
            v = nil
        end
    end
    self.cos = {}

    for i, v in pairs(self.tween) do
        if not isNull(v) then
            v:Kill()
            v = nil
        end
    end
    self.tween = {}
end

function ChapterBattleRoot:DisposeAll()
    self:CleanTweenAndCo()
    self.cacheNode = {}
end

function ChapterBattleRoot:GetBattleVos(battleGroupId)
    if isNull(self.battleIds) then
        self.battleIds = {}
        local allVos = CfUtils.GetCf(AutoIds.IdSetting6435,"ChapterBattleVo",true)
        for i, v in pairs(allVos) do
            if isNull(self.battleIds[v.battleGroupId]) then
                self.battleIds[v.battleGroupId] = {}
            end
            table.insert(self.battleIds[v.battleGroupId],v)
        end
    end

    if not isNull(self.battleIds[battleGroupId]) then
        return self.battleIds[battleGroupId]
    end

    return {}
end

function ChapterBattleRoot:GetCacheGo()
    local go = nil
    if self.cacheNode[1] then
        go = self.cacheNode[1]
        table.remove(self.cacheNode,1)
        return go
    end
end

function ChapterBattleRoot:InsertDescNodeGo(go)
    CfUtils.SetActive(go.gameObject,false)
    go.transform.localPosition = Vector3(self.RandomPos.x, self.RandomPos.y, 0)
    table.insert(self.cacheNode,go)
end

function ChapterBattleRoot:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ChapterBattleRoot